import Foundation
import AVFoundation
import CoreMedia

// Apple AVFoundation, using the synthetic ffmpeg MOV generated by generate.py.
let root = URL(fileURLWithPath: FileManager.default.currentDirectoryPath)
let input = root.appendingPathComponent("app/src/test/resources/mov-details/keyed.mov")
let output = root.appendingPathComponent("app/src/test/resources/mov-details/typed.mov")
try? FileManager.default.removeItem(at: output)
let asset = AVURLAsset(url: input)
guard let session = AVAssetExportSession(asset: asset, presetName: AVAssetExportPresetPassthrough) else { fatalError("Cannot create export session") }
session.outputURL = output
session.outputFileType = .mov
let definitions: [(String, CFString, NSNumber)] = [
    ("float32", kCMMetadataBaseDataType_Float32, NSNumber(value: Float(0.1))),
    ("float64", kCMMetadataBaseDataType_Float64, NSNumber(value: 1.234567890123)),
    ("int8", kCMMetadataBaseDataType_SInt8, NSNumber(value: Int8(-7))),
    ("int16", kCMMetadataBaseDataType_SInt16, NSNumber(value: Int16(-300))),
    ("int32", kCMMetadataBaseDataType_SInt32, NSNumber(value: Int32(-1234567))),
    ("int64", kCMMetadataBaseDataType_SInt64, NSNumber(value: Int64.min)),
    ("uint32", kCMMetadataBaseDataType_UInt32, NSNumber(value: UInt32.max)),
    ("uint64", kCMMetadataBaseDataType_UInt64, NSNumber(value: UInt64.max)),
]
session.metadata = definitions.map { key, type, value in
    let item = AVMutableMetadataItem()
    item.keySpace = .quickTimeMetadata
    item.key = "com.example.\(key)" as NSString
    item.dataType = type as String
    item.value = value
    return item
}
session.exportAsynchronously { }
let deadline = Date().addingTimeInterval(40)
while [.unknown, .waiting, .exporting].contains(session.status) && Date() < deadline {
    RunLoop.current.run(until: Date().addingTimeInterval(0.05))
}
guard session.status == .completed else { session.cancelExport(); fatalError("Export failed: \(String(describing: session.error))") }
print("Generated typed.mov with \(definitions.count) typed Apple metadata values")
